// One-off: prove in real Chrome that (a) the old cg-board (with its bindBoard
// listeners) is collectible after redrawAll while the instance is alive, and
// (b) the wrap subtree is collectible after destroy (the real ResizeObserver
// controller releases it only via disconnect()).
// Note: V8's exposed gc() applies with a delay, so WeakRefs are deref'd in a
// later evaluate, after gc() + a macrotask delay.
import { createServer } from 'node:http';
import { readFile, mkdtemp } from 'node:fs/promises';
import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';
import path from 'node:path';
import os from 'node:os';

const ROOT = 'D:/dev/ab-tasks/chessground-qwen-med-r1';
const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const PORT = 8472;
const CDP_PORT = 9334;
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };

const failures = [];
const check = (name, ok, detail) => {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? '  [' + detail + ']' : ''}`);
  if (!ok) failures.push(name);
};

const server = createServer(async (req, res) => {
  const url = new URL(req.url, 'http://x');
  if (url.pathname === '/favicon.ico') {
    res.writeHead(204);
    return res.end();
  }
  const p = path.join(ROOT, decodeURIComponent(url.pathname));
  try {
    const data = await readFile(p);
    res.writeHead(200, { 'content-type': MIME[path.extname(p)] || 'application/octet-stream' });
    res.end(data);
  } catch {
    res.writeHead(404);
    res.end('nf');
  }
});
await new Promise(r => server.listen(PORT, '127.0.0.1', r));

const profile = await mkdtemp(path.join(os.tmpdir(), 'cg-chrome2-'));
const chrome = spawn(
  CHROME,
  [
    '--headless=new',
    '--no-first-run',
    '--no-default-browser-check',
    '--disable-gpu',
    '--js-flags=--expose-gc',
    `--remote-debugging-port=${CDP_PORT}`,
    `--user-data-dir=${profile}`,
    'about:blank',
  ],
  { stdio: 'ignore' },
);
try {
  let up = false;
  for (let i = 0; i < 50 && !up; i++) {
    try {
      await (await fetch(`http://127.0.0.1:${CDP_PORT}/json/version`)).json();
      up = true;
    } catch {
      await sleep(200);
    }
  }
  if (!up) throw new Error('chrome did not start');

  const tab = await (await fetch(`http://127.0.0.1:${CDP_PORT}/json/new?about:blank`, { method: 'PUT' })).json();
  const ws = new WebSocket(tab.webSocketDebuggerUrl);
  await new Promise((r, j) => {
    ws.onopen = r;
    ws.onerror = () => j(new Error('ws connect failed'));
  });
  let id = 0;
  const pending = new Map();
  ws.onmessage = m => {
    const msg = JSON.parse(m.data);
    if (msg.id) {
      pending.get(msg.id)?.(msg);
      pending.delete(msg.id);
    }
  };
  const send = (method, params = {}) =>
    new Promise(r => {
      const i = ++id;
      pending.set(i, r);
      ws.send(JSON.stringify({ id: i, method, params }));
    });
  const evalJs = async expr => {
    const raw = (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result;
    if (raw.exceptionDetails) throw new Error(JSON.stringify(raw.exceptionDetails));
    return raw.result.value;
  };
  // gc + let the collection apply, then read a boolean probe expression
  const afterGc = async probe => {
    await evalJs(`gc(); gc(); gc(); true`);
    await sleep(300);
    return (await evalJs(probe)) === true;
  };

  await send('Runtime.enable');
  await send('Page.enable');
  await send('Page.navigate', { url: `http://127.0.0.1:${PORT}/demo.html` });
  await sleep(800);

  // 0. sanity: mechanics work (detached div collectible; in-tree div not)
  await evalJs(
    `(() => {
      let loose = document.createElement('div');
      const looseRef = new WeakRef(loose);
      loose = null;
      const kept = document.createElement('div');
      document.body.appendChild(kept);
      const keptRef = new WeakRef(kept);
      window.__s = { looseRef, keptRef, keep: kept };
      return true;
    })()`,
  );
  check('sanity: detached div collectible', await afterGc(`window.__s.looseRef.deref() === undefined`));
  check('sanity: in-tree div still alive (control)', await afterGc(`window.__s.keptRef.deref() !== undefined`));
  await evalJs(`window.__s = null; true`);

  // 1. old board (with its bindBoard listeners) collectible after redrawAll,
  //    while the chessground instance stays alive
  await evalJs(
    `(async () => {
      const { Chessground } = await import('/dist/chessground.js');
      const wrap = document.createElement('div');
      document.body.appendChild(wrap);
      const cg = Chessground(wrap, {});
      let board1 = cg.state.dom.elements.board;
      const boardRef = new WeakRef(board1);
      cg.redrawAll();
      board1 = null;
      window.__t = { cg, boardRef };
      return true;
    })()`,
  );
  check('old cg-board (with listeners) collectible after redrawAll, instance alive', await afterGc(`window.__t.boardRef.deref() === undefined`));
  await evalJs(`window.__t = null; true`);

  // 2. destroy: the real RO controller must release the wrap subtree
  await evalJs(
    `(async () => {
      const { Chessground } = await import('/dist/chessground.js');
      const wrap = document.createElement('div');
      document.body.appendChild(wrap);
      const wrapRef = new WeakRef(wrap);
      const cg = Chessground(wrap, {});
      cg.destroy();
      wrap.remove();
      window.__w = { check: () => wrapRef.deref() !== undefined };
      return true;
    })()`,
  );
  check('wrap subtree collectible after destroy', await afterGc(`window.__w.check() === false`));
  await evalJs(`window.__w = null; true`);

  // 3. control: a live board (referenced by the instance + DOM tree) stays alive
  await evalJs(
    `(async () => {
      const { Chessground } = await import('/dist/chessground.js');
      const wrap = document.createElement('div');
      document.body.appendChild(wrap);
      const cg = Chessground(wrap, {});
      let b = cg.state.dom.elements.board;
      const r = new WeakRef(b);
      b = null;
      window.__c = { cg, wrap, check: () => r.deref() !== undefined };
      return true;
    })()`,
  );
  check('control: live board still reachable', await afterGc(`window.__c.check() === true`));

  ws.close();
} finally {
  chrome.kill('SIGTERM');
  server.close();
}

if (failures.length) {
  console.error(`\n${failures.length} check(s) FAILED`);
  process.exit(1);
}
console.log('\nAll retention checks passed.');
process.exit(0);

